//! Cross-language parity against golden files generated by the Apple
//! `TabToolKit` implementation.
//!
//! Every file in `testdata/golden` is loaded, its inputs are rebuilt, the Rust
//! implementation runs on them, and the results are compared deeply. The
//! Swift implementation is the binding contract, so these tests are the
//! authority for collation, encoding, clipboard and export behavior.
#![cfg(target_os = "macos")]

use std::path::PathBuf;

use base64::Engine;
use base64::engine::general_purpose::STANDARD;
use serde_json::{Value, json};
use tabtool_core::{
    CsvConfiguration, CsvFormatDetector, CsvParser, CsvTable, CsvWriteIssue, CsvWriter, Encoding,
    ExportInput, FilterCriterion, FilterOperator, Locale, RowFilter, SortDirection, export_data,
    export_preflight_issue, make_tsv, parse_tsv, row_order_sorted_by,
};

/// Directory holding the Swift-generated golden files.
fn golden_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../testdata/golden")
}

/// Every golden file, sorted by locale for deterministic failures.
fn golden_files() -> Vec<PathBuf> {
    let mut files: Vec<PathBuf> = std::fs::read_dir(golden_dir())
        .expect("golden directory exists")
        .map(|entry| entry.expect("directory entry is readable").path())
        .filter(|path| {
            path.extension()
                .is_some_and(|extension| extension == "json")
        })
        .collect();
    files.sort();
    assert!(!files.is_empty(), "no golden files found");
    files
}

fn text(value: &Value) -> &str {
    value.as_str().expect("golden field is a string")
}

fn flag(value: &Value) -> bool {
    value.as_bool().expect("golden field is a boolean")
}

fn number(value: &Value) -> u64 {
    value.as_u64().expect("golden field is an unsigned integer")
}

/// The encoding named by its display-order identifier.
fn encoding(value: &Value) -> Encoding {
    let id = u16::try_from(number(value)).expect("encoding id fits u16");
    Encoding::from_id(id).unwrap_or_else(|| panic!("unknown encoding id {id}"))
}

/// Rows from a JSON array of arrays.
fn rows(value: &Value) -> Vec<Vec<String>> {
    value
        .as_array()
        .expect("golden rows are an array")
        .iter()
        .map(|row| {
            row.as_array()
                .expect("golden row is an array")
                .iter()
                .map(|cell| text(cell).to_owned())
                .collect()
        })
        .collect()
}

/// One flat array of strings.
fn cells(value: &Value) -> Vec<String> {
    value
        .as_array()
        .expect("golden cells are an array")
        .iter()
        .map(|cell| text(cell).to_owned())
        .collect()
}

/// A configuration in the golden JSON shape.
fn configuration(value: &Value) -> CsvConfiguration {
    CsvConfiguration {
        encoding: encoding(&value["encoding"]),
        column_separator: text(&value["separator"]).to_owned(),
        quote_character: text(&value["quote"]).to_owned(),
        escape_character: text(&value["escape"]).to_owned(),
        decimal_mark: text(&value["decimalMark"]).to_owned(),
        first_row_as_header: flag(&value["header"]),
    }
}

/// The golden JSON shape of a configuration.
fn configuration_json(configuration: &CsvConfiguration) -> Value {
    json!({
        "encoding": configuration.encoding.id(),
        "separator": configuration.column_separator,
        "quote": configuration.quote_character,
        "escape": configuration.escape_character,
        "decimalMark": configuration.decimal_mark,
        "header": configuration.first_row_as_header,
    })
}

/// The locale stored in the golden file.
fn locale(document: &Value) -> Locale {
    text(&document["locale"])
        .replace('_', "-")
        .parse()
        .expect("golden locale is valid")
}

fn sort_direction(value: &Value) -> SortDirection {
    match text(value) {
        "ascending" => SortDirection::Ascending,
        "descending" => SortDirection::Descending,
        other => panic!("unknown sort direction {other:?}"),
    }
}

fn filter_operator(name: &str) -> FilterOperator {
    match name {
        "equals" => FilterOperator::Equals,
        "notEquals" => FilterOperator::NotEquals,
        "contains" => FilterOperator::Contains,
        "notContains" => FilterOperator::NotContains,
        "beginsWith" => FilterOperator::BeginsWith,
        "endsWith" => FilterOperator::EndsWith,
        "greaterThan" => FilterOperator::GreaterThan,
        "lessThan" => FilterOperator::LessThan,
        "greaterOrEqual" => FilterOperator::GreaterOrEqual,
        "lessOrEqual" => FilterOperator::LessOrEqual,
        "isEmpty" => FilterOperator::IsEmpty,
        "isNotEmpty" => FilterOperator::IsNotEmpty,
        "matchesRegex" => FilterOperator::MatchesRegex,
        other => panic!("unknown filter operator {other:?}"),
    }
}

fn issue_name(issue: CsvWriteIssue) -> &'static str {
    match issue {
        CsvWriteIssue::UnencodableText => "unencodableText",
        CsvWriteIssue::AmbiguousOutput => "ambiguousOutput",
    }
}

/// Rebuilds every fixture input and compares detection, rows and writes.
fn check_fixtures(locale_name: &str, document: &Value) {
    let encodings = document["encodings"]
        .as_array()
        .expect("encodings are an array");
    assert_eq!(
        encodings.iter().map(text).collect::<Vec<_>>(),
        Encoding::ALL
            .iter()
            .map(|encoding| encoding.display_name())
            .collect::<Vec<_>>(),
        "{locale_name}: encoding list"
    );

    let fixtures = document["fixtures"]
        .as_array()
        .expect("fixtures are an array");
    let mut expected_names: Vec<&str> = tabtool_testdata::fixture_names()
        .iter()
        .copied()
        .filter(|name| name.starts_with("Reading/") || name.starts_with("Heuristic/"))
        .collect();
    expected_names.sort_unstable();
    let mut actual_names: Vec<&str> = fixtures
        .iter()
        .map(|fixture| text(&fixture["name"]))
        .collect();
    actual_names.sort_unstable();
    assert_eq!(actual_names, expected_names, "{locale_name}: fixture list");

    for fixture in fixtures {
        let name = text(&fixture["name"]);
        let data = tabtool_testdata::fixture(name);
        let context = format!("{locale_name}: fixture {name}");

        let detected = CsvFormatDetector::new(&data, false).detect();
        assert_eq!(
            configuration_json(&detected),
            fixture["detected"],
            "{context}: detection"
        );

        let mut parser = CsvParser::from_bytes(&data, &detected)
            .unwrap_or_else(|error| panic!("{context}: parser setup failed: {error:?}"));
        assert_eq!(
            parser.had_utf8_bom(),
            flag(&fixture["hadUTF8BOM"]),
            "{context}: hadUTF8BOM"
        );
        let parsed = parser
            .read_all()
            .unwrap_or_else(|error| panic!("{context}: parse failed: {error:?}"));
        assert_eq!(json!(parsed), fixture["rows"], "{context}: rows");

        let table = CsvTable::from_rows(parsed, None, 1);
        let include_utf8_bom = flag(&fixture["hadUTF8BOM"]);
        for write in fixture["writes"].as_array().expect("writes are an array") {
            let write_encoding = encoding(&write["encoding"]);
            let write_context = format!("{context}: write {write_encoding:?}");
            let write_configuration = configuration(&write["configuration"]);
            assert_eq!(
                write_configuration.encoding, write_encoding,
                "{write_context}: encoding mismatch in configuration"
            );

            if let Err(error) = write_encoding.decode(&data) {
                assert_eq!(
                    error,
                    tabtool_core::CsvError::CannotDecodeData,
                    "{write_context}: decode error"
                );
                assert_eq!(
                    write.get("skip").and_then(Value::as_str),
                    Some("cannotDecodeData"),
                    "{write_context}: Rust rejected bytes Foundation accepted"
                );
                continue;
            }
            assert!(
                write.get("skip").is_none(),
                "{write_context}: unexpected skip {write:?}"
            );

            let writer = CsvWriter {
                table: &table,
                header: None,
                configuration: &write_configuration,
                include_utf8_bom,
                allow_ambiguous_output: false,
            };
            let bytes = writer
                .data()
                .unwrap_or_else(|error| panic!("{write_context}: write failed: {error:?}"));
            assert_eq!(
                STANDARD.encode(bytes),
                text(&write["base64"]),
                "{write_context}: bytes"
            );
        }
    }
}

/// Rebuilds every sort case and compares the row order.
fn check_sort(locale_name: &str, document: &Value, locale: &Locale) {
    let cases = document["sort"]
        .as_array()
        .expect("sort cases are an array");
    assert_eq!(cases.len(), 4, "{locale_name}: sort case count");
    for case in cases {
        let name = text(&case["name"]);
        let values = cells(&case["cells"]);
        assert_eq!(values.len(), 40, "{locale_name}: sort corpus size");
        let table = CsvTable::from_rows(
            values.iter().map(|cell| vec![cell.clone()]).collect(),
            None,
            1,
        );
        let order = row_order_sorted_by(
            &table,
            0,
            sort_direction(&case["direction"]),
            text(&case["decimalMark"]),
            locale,
        );
        let expected: Vec<usize> = case["order"]
            .as_array()
            .expect("order is an array")
            .iter()
            .map(|index| usize::try_from(number(index)).expect("order index fits usize"))
            .collect();
        assert_eq!(order, expected, "{locale_name}: sort {name}");
    }
}

/// Rebuilds every filter case and compares the matching rows.
fn check_filters(locale_name: &str, document: &Value, locale: &Locale) {
    for case in document["filters"]
        .as_array()
        .expect("filter cases are an array")
    {
        let name = text(&case["name"]);
        let table = CsvTable::from_rows(rows(&case["rows"]), None, 3);
        let criteria: Vec<FilterCriterion> = case["criteria"]
            .as_array()
            .expect("criteria are an array")
            .iter()
            .map(|criterion| {
                let column = criterion["column"]
                    .as_i64()
                    .expect("criterion column is an integer");
                let column_id = usize::try_from(column)
                    .ok()
                    .and_then(|column| table.columns.get(column))
                    .map(|column| column.id);
                FilterCriterion {
                    id: 1,
                    is_enabled: flag(&criterion["enabled"]),
                    column_id,
                    op: filter_operator(text(&criterion["op"])),
                    value: text(&criterion["value"]).to_owned(),
                }
            })
            .collect();
        let matching = RowFilter { criteria }.matching_rows(&table, ".", locale);
        let expected: Vec<usize> = case["matching"]
            .as_array()
            .expect("matching is an array")
            .iter()
            .map(|index| usize::try_from(number(index)).expect("matching index fits usize"))
            .collect();
        assert_eq!(matching, expected, "{locale_name}: filter {name}");
    }
}

/// Rebuilds the clipboard parse and make cases.
fn check_clipboard(locale_name: &str, document: &Value) {
    for case in document["clipboard"]["parse"]
        .as_array()
        .expect("clipboard parse cases are an array")
    {
        let input = text(&case["input"]);
        assert_eq!(
            json!(parse_tsv(input)),
            case["rows"],
            "{locale_name}: clipboard parse {input:?}"
        );
    }

    for case in document["clipboard"]["make"]
        .as_array()
        .expect("clipboard make cases are an array")
    {
        let output = make_tsv(
            &rows(&case["rows"]),
            text(&case["decimalMark"]),
            text(&case["separator"]),
        );
        assert_eq!(
            output,
            text(&case["output"]),
            "{locale_name}: clipboard make {:?}",
            case["rows"]
        );
    }
}

/// Rebuilds every export case, including its preflight issue and bytes.
fn check_export(locale_name: &str, document: &Value) {
    for case in document["export"]
        .as_array()
        .expect("export cases are an array")
    {
        let name = text(&case["name"]);
        let headers = match &case["headers"] {
            Value::Null => None,
            header_values => Some(cells(header_values)),
        };
        let table = CsvTable::from_rows(rows(&case["rows"]), headers, 1);
        let document_configuration = configuration(&case["document"]);
        let export_configuration = configuration(&case["export"]);
        let input = ExportInput {
            table: &table,
            document_configuration: &document_configuration,
            export_configuration: &export_configuration,
        };
        let context = format!("{locale_name}: export {name}");

        match export_preflight_issue(&input) {
            None => {
                assert!(
                    case["preflight"].is_null(),
                    "{context}: unexpected preflight {:?}",
                    case["preflight"]
                );
                let bytes = export_data(&input, false)
                    .unwrap_or_else(|error| panic!("{context}: export failed: {error:?}"));
                assert_eq!(
                    STANDARD.encode(bytes),
                    text(&case["base64"]),
                    "{context}: bytes"
                );
            }
            Some(issue) => {
                assert_eq!(
                    issue_name(issue),
                    text(&case["preflight"]),
                    "{context}: preflight"
                );
                assert!(case["base64"].is_null(), "{context}: bytes on failure");
            }
        }
    }
}

#[test]
fn rust_matches_every_swift_golden() {
    let mut locales = Vec::new();
    for path in golden_files() {
        let contents = std::fs::read_to_string(&path).expect("golden file is readable");
        let document: Value = serde_json::from_str(&contents).expect("golden file is valid JSON");
        let locale_name = text(&document["locale"]);
        let locale = locale(&document);
        locales.push(locale_name.to_owned());

        check_fixtures(locale_name, &document);
        check_sort(locale_name, &document, &locale);
        check_filters(locale_name, &document, &locale);
        check_clipboard(locale_name, &document);
        check_export(locale_name, &document);
    }
    locales.sort_unstable();
    assert_eq!(
        locales,
        ["de_DE", "en_US", "fr_FR", "ja_JP", "ko_KR", "zh_CN"],
        "golden locale set"
    );
}
